import { validateYaml } from "./yaml-validator";
import path from "node:path";

const HELP_MESSAGE = `Usage: bun run validate-yaml <file>
       echo "yaml content" | bun run validate-yaml
...`;

async function main(): Promise<void> {
  const arg = process.argv[2];
  if (arg === "--help") { console.log(HELP_MESSAGE); process.exit(0); }

  let content: string;
  let source: string;

  if (arg) {
    const file = Bun.file(arg);
    if (!(await file.exists())) {
      console.error(`Error: File not found: ${arg}`);
      process.exit(1);
    }
    content = await file.text();
    source = path.basename(arg);
  } else if (!process.stdin.isTTY) {
    content = await Bun.stdin.text();
    source = "stdin";
  } else {
    console.log(HELP_MESSAGE); process.exit(0); return;
  }

  const result = validateYaml(content);
  if (result.valid) {
    console.log(`Valid YAML: ${source}`); process.exit(0);
  } else {
    console.error(`Invalid YAML: ${source}`);
    console.error(`Error: ${result.error}`);
    if (result.line !== undefined) console.error(`  at line ${result.line}`);
    process.exit(1);
  }
}
main();
```

