/** Result of YAML validation. */
export interface YamlValidationResult {
  /** Whether the YAML content is syntactically valid. */
  valid: boolean;
  /** Error message if validation failed. */
  error?: string;
  /** Line number where the error was detected, if available. */
  line?: number;
}

/**
 * Validate whether a string contains syntactically valid YAML.
 * Uses Bun's built-in YAML parser. Empty input is treated as valid.
 */
export function validateYaml(content: string): YamlValidationResult {
  if (content.trim() === "") {
    return { valid: true };
  }

  try {
    Bun.YAML.parse(content);
    return { valid: true };
  } catch (err) {
    const message =
      err instanceof Error ? err.message : "Unknown YAML parsing error";
    const lineMatch = message.match(/line (\d+)/i);
    const line = lineMatch ? parseInt(lineMatch[1], 10) : undefined;

    return {
      valid: false,
      error: message,
      ...(line !== undefined && { line }),
    };
  }
}

