import { describe, expect, test } from "bun:test";
import { validateYaml } from "./yaml-validator";

describe("validateYaml", () => {
  describe("valid YAML", () => {
    test("simple mapping returns valid", () => {
      const result = validateYaml("key: value");
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("nested mapping returns valid", () => {
      const yaml = `parent:
  child1: value1
  child2:
    grandchild: value2`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("sequence returns valid", () => {
      const result = validateYaml("- item1\n- item2");
      expect(result.valid).toBe(true);
    });

    test("multiline block scalar returns valid", () => {
      const yaml = `description: |
  This is a multiline
  block scalar value`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("YAML with comments returns valid", () => {
      const yaml = `# This is a comment
key: value # inline comment
# another comment`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });
  });

  describe("empty input", () => {
    test("empty string returns valid", () => {
      const result = validateYaml("");
      expect(result.valid).toBe(true);
    });

    test("whitespace-only string returns valid", () => {
      const result = validateYaml("  \n  ");
      expect(result.valid).toBe(true);
    });
  });

  describe("invalid YAML", () => {
    test("bad indentation returns invalid with error", () => {
      const yaml = `parent:
  child1: value1
 child2: value2`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(typeof result.error).toBe("string");
    });

    test("malformed syntax returns invalid with error", () => {
      const yaml = `key: value
  : broken: yaml: [`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(typeof result.error).toBe("string");
    });

    test("error result includes non-empty description", () => {
      const yaml = `key: value
  : broken`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.length).toBeGreaterThan(0);
    });
  });
});

